package com.wizzadrds.theworldremembers.knowledge;
import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*;
public final class KnowledgeManager extends SavedData{private final Map<UUID,List<KnowledgeFact>> facts=new HashMap<>(); private static final Codec<KnowledgeFact> F=RecordCodecBuilder.create(i->i.group(Codec.STRING.xmap(UUID::fromString,UUID::toString).fieldOf("holder").forGetter(KnowledgeFact::holder),Codec.STRING.fieldOf("eventType").forGetter(KnowledgeFact::eventType),Codec.STRING.xmap(UUID::fromString,UUID::toString).fieldOf("subject").forGetter(KnowledgeFact::subject),Codec.STRING.xmap(UUID::fromString,UUID::toString).optionalFieldOf("source","").forGetter(f->f.source()==null?"":f.source().toString()),Codec.STRING.xmap(KnowledgeProvenance::valueOf,KnowledgeProvenance::name).fieldOf("provenance").forGetter(KnowledgeFact::provenance),Codec.LONG.fieldOf("observedTick").forGetter(KnowledgeFact::observedTick),Codec.DOUBLE.fieldOf("confidence").forGetter(KnowledgeFact::confidence),Codec.INT.fieldOf("hops").forGetter(KnowledgeFact::hops)).apply(i,(h,e,s,src,p,t,c,hop)->new KnowledgeFact(h,e,s,src.isEmpty()?null:UUID.fromString(src),p,t,c,hop))); private static final Codec<KnowledgeManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),F.listOf()).xmap(m->{var k=new KnowledgeManager();k.facts.putAll(m);return k;},k->k.facts); private static final SavedDataType<KnowledgeManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","knowledge"),KnowledgeManager::new,C,null); public static KnowledgeManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new KnowledgeManager():l.getDataStorage().computeIfAbsent(TYPE);} public void remember(KnowledgeFact f){var list=facts.computeIfAbsent(f.holder(),x->new ArrayList<>());if(list.stream().noneMatch(x->x.eventType().equals(f.eventType())&&x.subject().equals(f.subject()))){list.add(f);setDirty();}} public List<KnowledgeFact> facts(UUID h){return List.copyOf(facts.getOrDefault(h,List.of()));} public void report(UUID from,UUID to,String type,UUID subject,long tick){for(var f:facts(from))if(f.eventType().equals(type)&&f.subject().equals(subject)){var p=f.provenance()==KnowledgeProvenance.DIRECT?KnowledgeProvenance.REPORTED:KnowledgeProvenance.RUMORED;if(f.hops()<4)remember(new KnowledgeFact(to,type,subject,from,p,tick,f.confidence()*(p==KnowledgeProvenance.REPORTED?.8:.7),f.hops()+1));}}}
